<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class Mmediummaterialmodel extends CI_Model {    function fnGetMediumMaterialInfo($VarData = '', $VarStatus = '', $VarId = '') {        $this->db->select('id,medium_material,updatedby,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_MEDIUM_MATERIAL);        // if ($VarStatus <> '') {        //     $this->db->where_in('status', array($VarStatus));        // } else {        //     $this->db->where_in('status', array(1, 2));        // }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarData <> '') {            $ArrWhere['medium_material'] = trim($VarData);        }        if (!empty($ArrWhere)) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheckMediumMaterial($VarData = '', $VarId = '',$VarCompanyId='') {        $this->db->from(KN_MASTER_MEDIUM_MATERIAL);        //$ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['medium_material'] = trim($VarData);        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveMediumMaterial($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetMediumMaterialInfo($ArrUpdateData['medium_material'], 1);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_MEDIUM_MATERIAL, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This medium / material already exists";            }        } else {            $VarAlreadyExists = $this->fnCheckMediumMaterial($ArrUpdateData['medium_material'], $VarId,$ArrUpdateData['companyid']);            if (empty($VarAlreadyExists)) {                if ($this->db->update(KN_MASTER_MEDIUM_MATERIAL, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This medium / material already exists";            }        }        return $ArrResult;    }    public function mediumMaterialWhereCond($VarName = '', $VarStatus = '',$VarCompanyId='') {        if ($VarName <> '') {            $ArrWhere[] = "medium_material LIKE '%" . $VarName . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "m.status = " . $VarStatus;        } else {            $ArrWhere[] = "m.status in(1,2)";        }        if ($VarCompanyId <> '') {            $ArrWhere[] = "m.companyid = ".$VarCompanyId;        }        $VarWhere = " WHERE ". implode(" AND ", $ArrWhere);        return $VarWhere;    }    public function fnCountMediumMaterial($VarName = '', $VarStatus = '',$VarCompanyId='') {        $VarWhere = $this->mediumMaterialWhereCond($VarName, $VarStatus,$VarCompanyId);        $VarSql = "SELECT count(1) as trec  FROM ".KN_MASTER_MEDIUM_MATERIAL." AS m".$VarWhere;        $ObjRows = $this->db->query($VarSql)->row();        return $ObjRows->trec;    }    function fnListMediumMaterial($VarName = '', $VarStatus = '',$VarCompanyId='',$VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder) {        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('medium_material', 'm.status', 'm.updatedby', 'm.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $VarWhere = $this->mediumMaterialWhereCond($VarName, $VarStatus,$VarCompanyId);        //  removed this line . " limit " . $VarLimitInfo in below query        $VarSql = "SELECT m.id,medium_material,m.dateupdated,m.status,contactname FROM " . KN_MASTER_MEDIUM_MATERIAL . " AS m         LEFT JOIN ".KN_USERS." AS u ON m.updatedby = u.id ". $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder;        return $this->db->query($VarSql);    }    function changeMedMaterialStatus($VarCheckBoxId, $VarStatus) {        $ArrId = json_decode($VarCheckBoxId, true);        $this->db->where_in('id', $ArrId);        $this->db->update(KN_MASTER_MEDIUM_MATERIAL, array('status' => $VarStatus));    }}